48	     * Change a person's name and record their grade from a date (null: the sheet's today), keeping the
49	     * grades already recorded, from the version of the person the editor loaded; refused when someone
50	     * has saved the person since, or when the name is in use by another person.
51	     */
52	    @Transactional
53	    public Person edit(String sheetId, String user, long personId, long version, String name, String grade,
54	            LocalDate gradeFrom) {
55	        Person person = people.findByIdAndSheetId(personId, sheetId)
56	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
57	        if (person.getVersion() != version) {
58	            throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
59	                    "Someone else has saved this person since it was opened.");
60	        }
61	        requireNameFree(sheetId, name, person.getId());
62	        Rollups.Rollup before = rollups.take(sheetId);
63	        LocalDate today = sheets.today(sheetId);
64	        person.setName(name);
65	        person.gradeFrom(grade, gradeFrom != null ? gradeFrom : today);
66	        Person saved = people.saveAndFlush(person);
67	        audited("PERSON_EDITED", sheetId, user, saved, today);
68	        rollups.audit(sheetId, user, before);
69	        return saved;
70	    }
71	
72	    /** Retire a person from a date; with no date, from the sheet's today. */
73	    @Transactional
74	    public Person retire(String sheetId, String user, long personId, LocalDate from) {
75	        Person person = people.findByIdAndSheetId(personId, sheetId)
76	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
77	        person.retire(from != null ? from : sheets.today(sheetId));
78	        Person saved = people.saveAndFlush(person);
79	        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
80	                + " name=" + saved.getName() + " from=" + saved.getRetiredFrom());
81	        return saved;
82	    }
83	
84	    /**
85	     * Put a person on hold from a date (null: the sheet's today) to a date (null: no end); refused
86	     * when the to-date is before the from-date. Their figures and the sheet's totals move as their
87	     * OPEN and PENDING claims dated within it, not bound by a statement, leave the live totals.
88	     */
89	    @Transactional
90	    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
91	        Person person = people.findByIdAndSheetId(personId, sheetId)
92	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
93	        LocalDate start = from != null ? from : sheets.today(sheetId);
94	        if (to != null && to.isBefore(start)) {
95	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
96	        }
97	        Rollups.Rollup before = rollups.take(sheetId);
98	        person.hold(start, to);
99	        Person saved = people.saveAndFlush(person);
100	        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user
101	                + " name=" + saved.getName() + " from=" + start);
102	        rollups.audit(sheetId, user, before);
103	        return saved;
104	    }
105	
106	    /**
107	     * Name another person on the sheet as a patron of this one; refused for the person themselves and
108	     * for someone already their patron.
109	     */
110	    @Transactional
111	    public Person addPatron(String sheetId, String user, long personId, long patronId) {
112	        Person person = people.findByIdAndSheetId(personId, sheetId)
113	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
114	        Person patron = people.findByIdAndSheetId(patronId, sheetId)
115	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet."));
116	        if (person.getId().equals(patron.getId())) {
117	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
118	        }
119	        if (!person.addPatron(patron.getId())) {
120	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron.");
121	        }
122	        Person saved = people.saveAndFlush(person);
123	        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
124	                + " name=" + saved.getName() + " patron=" + patron.getName());
125	        return saved;
126	    }
127	
128	    /** Record the change to the person, with the grade in force on the sheet's today, once it is committed. */
129	    private void audited(String event, String sheetId, String user, Person person, LocalDate today) {
130	        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
131	                + " name=" + person.getName() + " grade=" + person.gradeOn(today));
132	    }
133	
134	    /** Refuse a name already held on the sheet by anyone other than {@code self}. */
135	    private void requireNameFree(String sheetId, String name, Long self) {
136	        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
137	                .filter(holder -> !holder.getId().equals(self))
138	                .ifPresent(holder -> {
139	                    throw nameInUse();
140	                });
141	    }
142	
143	    static ResponseStatusException nameInUse() {
144	        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
145	    }
146	}
