149	import java.math.BigDecimal;
150	import java.math.RoundingMode;
151	import java.time.Instant;
152	import net.officefloor.hq.app.Audit;
153	import java.time.LocalDate;
154	import net.officefloor.hq.app.rollup.Rollups;
155	import org.springframework.stereotype.Service;
156	import org.springframework.transaction.annotation.Transactional;
157	
158	/** Loads sheets by id; an id never loaded before starts a new, empty sheet. */
159	@Service
160	public class SheetService {
161	
162	    private final SheetRepository sheets;
163	    private final Rollups rollups;
164	    private final Audit audit;
165	
166	    public SheetService(SheetRepository sheets, Rollups rollups, Audit audit) {
167	        this.sheets = sheets;
168	        this.rollups = rollups;
169	        this.audit = audit;
170	    }
171	
172	    /** Load a sheet; a new sheet's today starts as the real date. */
173	    @Transactional
174	    public synchronized Sheet load(String id) {
175	        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, Instant.now(), LocalDate.now())));
176	    }
177	
178	    /**
179	     * The sheet's today. Every date-dependent decision and every default date on a sheet uses
180	     * this, never the real clock.
181	     */
182	    @Transactional(readOnly = true)
183	    public LocalDate today(String id) {
184	        return load(id).getToday();
185	    }
186	
187	    /**
188	     * Take the sheet's lock, holding it until the caller's transaction ends, so changes that check
189	     * the sheet's other rows before writing are made one at a time.
190	     */
191	    @Transactional
192	    public Sheet lock(String id) {
193	        load(id);
194	        return sheets.findLockedById(id).orElseThrow();
195	    }
196	
197	    /** Change the sheet's today, auditing the figures that moves. */
198	    @Transactional
199	    public synchronized Sheet setToday(String id, String user, LocalDate today) {
200	        Sheet sheet = load(id);
201	        Rollups.Rollup before = rollups.take(id);
202	        sheet.setToday(today);
203	        Sheet saved = sheets.saveAndFlush(sheet);
204	        rollups.audit(id, user, before);
205	        return saved;
206	    }
207	
208	    /** The sheet's clerk limit; null when there is none. */
209	    @Transactional(readOnly = true)
210	    public BigDecimal clerkLimit(String id) {
211	        return load(id).getClerkLimit();
212	    }
213	
214	    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today), auditing the change. */
215	    @Transactional
216	    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
217	        return setDated(id, user, Sheet.CLERK_LIMIT, money(limit), from, false);
218	    }
219	
220	    /** Record the sheet's cap (null: no cap) from a date, auditing the change and the figures it moves. */
221	    @Transactional
222	    public Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
223	        return setDated(id, user, Sheet.CAP, money(cap), from, true);
224	    }
225	
226	    /** Record the sheet's floor from a date, auditing the change and the figures it moves. */
227	    @Transactional
228	    public Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
229	        return setDated(id, user, Sheet.FLOOR, money(floor), from, true);
230	    }
231	
232	    /** Record the sheet's terms, in days, from a date, auditing the change; claims keep their due-by. */
233	    @Transactional
234	    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
235	        return setDated(id, user, Sheet.TERMS, Integer.toString(terms), from, true);
236	    }
237	
238	    /**
239	     * Record a grade's own terms, in days (null: the sheet's terms), from a date, auditing the change.
240	     * Claims keep their due-by.
241	     */
242	    @Transactional
243	    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
244	        return setDated(id, user, Sheet.gradeTermsKey(grade), terms == null ? null : terms.toString(), from, true);
245	    }
246	
247	    /** Record the sheet's late percent from a date, auditing the change and the figures it moves. */
248	    @Transactional
249	    public Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
250	        return setDated(id, user, Sheet.LATE_PCT, money(latePct), from, true);
251	    }
252	
253	    /**
254	     * Record a dated setting's value (null: none) from a date, the sheet's today when none is given,
255	     * replacing any value recorded from that date. The change is audited, with the from-date when one
256	     * was given, and so are the figures it moves when it can move any.
257	     */
258	    private Sheet setDated(String id, String user, String key, String value, LocalDate from, boolean movesFigures) {
259	        Sheet sheet = lock(id);
260	        Rollups.Rollup before = movesFigures ? rollups.take(id) : null;
261	        sheet.record(key, from == null ? sheet.getToday() : from, value);
262	        Sheet saved = sheets.saveAndFlush(sheet);
263	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value="
264	                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
265	        if (movesFigures) {
266	            rollups.audit(id, user, before);
267	        }
268	        return saved;
269	    }
270	
271	    /** A figure with two decimals as text; null stays null. */
272	    private static String money(BigDecimal value) {
273	        return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
274	    }
275	
276	    /** Change the sheet's policy date (null: the sheet's today), auditing the change and the figures it moves. */
277	    @Transactional
278	    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
279	        Sheet sheet = lock(id);
280	        Rollups.Rollup before = rollups.take(id);
281	        sheet.setPolicyDate(policyDate);
282	        Sheet saved = sheets.saveAndFlush(sheet);
283	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
284	                + (saved.getPolicyDate() == null ? "" : saved.getPolicyDate().toString()));
285	        rollups.audit(id, user, before);
286	        return saved;
287	    }
288	
289	    /** Change the sheet's period-numbering-from date (null: off), auditing the change. */
290	    @Transactional
291	    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
292	        Sheet sheet = lock(id);
293	        sheet.setPeriodNumberingFrom(from);
294	        Sheet saved = sheets.saveAndFlush(sheet);
295	        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
296	                + (saved.getPeriodNumberingFrom() == null ? "" : saved.getPeriodNumberingFrom().toString()));
297	        return saved;
298	    }
299	}
