    }

    /**
     * Change a person's name and record their grade from a date (null: the sheet's today), keeping the
     * grades already recorded, from the version of the person the editor loaded; refused when someone
     * has saved the person since, or when the name is in use by another person.
     */
    @Transactional
    public Person edit(String sheetId, String user, long personId, long version, String name, String grade,
            LocalDate gradeFrom) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        if (person.getVersion() != version) {
            throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,
                    "Someone else has saved this person since it was opened.");
        }
        requireNameFree(sheetId, name, person.getId());
        Rollups.Rollup before = rollups.take(sheetId);
        LocalDate today = sheets.today(sheetId);
        person.setName(name);
        person.gradeFrom(grade, gradeFrom != null ? gradeFrom : today);
        Person saved = people.saveAndFlush(person);
        audited("PERSON_EDITED", sheetId, user, saved, today);
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /** Retire a person from a date; with no date, from the sheet's today. */
    @Transactional
    public Person retire(String sheetId, String user, long personId, LocalDate from) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        person.retire(from != null ? from : sheets.today(sheetId));
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " from=" + saved.getRetiredFrom());
        return saved;
    }

    /**
     * Put a person on hold from a date (null: the sheet's today) to a date (null: no end); refused
     * when the to-date is before the from-date. Their figures and the sheet's totals move as their
     * OPEN and PENDING claims dated within it, not bound by a statement, leave the live totals.
     */
    @Transactional
    public Person hold(String sheetId, String user, long personId, LocalDate from, LocalDate to) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        LocalDate start = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(start)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A hold cannot end before it starts.");
        }
        Rollups.Rollup before = rollups.take(sheetId);
        person.hold(start, to);
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " from=" + start);
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /**
     * Name another person on the sheet as a patron of this one; refused for the person themselves and
     * for someone already their patron.
     */
    @Transactional
    public Person addPatron(String sheetId, String user, long personId, long patronId) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron on this sheet."));
        if (person.getId().equals(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be their own patron.");
        }
        if (!person.addPatron(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That person is already a patron.");
        }
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user
                + " name=" + saved.getName() + " patron=" + patron.getName());
        return saved;
    }

    /** Record the change to the person, with the grade in force on the sheet's today, once it is committed. */
    private void audited(String event, String sheetId, String user, Person person, LocalDate today) {
        audit.recordOnCommit(event + " sheet=" + sheetId + " by=" + user
                + " name=" + person.getName() + " grade=" + person.gradeOn(today));
    }

    /** Refuse a name already held on the sheet by anyone other than {@code self}. */
    private void requireNameFree(String sheetId, String name, Long self) {
        people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
                .filter(holder -> !holder.getId().equals(self))
                .ifPresent(holder -> {
                    throw nameInUse();
                });
    }

    static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "That name is already in use on this sheet.");
    }
}
package net.officefloor.hq.app.sheet;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.Instant;
import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.rollup.Rollups;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads sheets by id; an id never loaded before starts a new, empty sheet. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Rollups rollups;
    private final Audit audit;

    public SheetService(SheetRepository sheets, Rollups rollups, Audit audit) {
        this.sheets = sheets;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** Load a sheet; a new sheet's today starts as the real date. */
    @Transactional
    public synchronized Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> sheets.save(new Sheet(id, Instant.now(), LocalDate.now())));
    }

    /**
     * The sheet's today. Every date-dependent decision and every default date on a sheet uses
     * this, never the real clock.
     */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /**
     * Take the sheet's lock, holding it until the caller's transaction ends, so changes that check
     * the sheet's other rows before writing are made one at a time.
     */
    @Transactional
    public Sheet lock(String id) {
        load(id);
        return sheets.findLockedById(id).orElseThrow();
    }

    /** Change the sheet's today, auditing the figures that moves. */
    @Transactional
    public synchronized Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        rollups.audit(id, user, before);
        return saved;
    }

    /** The sheet's clerk limit; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String id) {
        return load(id).getClerkLimit();
    }

    /** Record the sheet's clerk limit (null: no limit) from a date (null: the sheet's today), auditing the change. */
    @Transactional
    public Sheet setClerkLimit(String id, String user, BigDecimal limit, LocalDate from) {
        return setDated(id, user, Sheet.CLERK_LIMIT, money(limit), from, false);
    }

    /** Record the sheet's cap (null: no cap) from a date, auditing the change and the figures it moves. */
    @Transactional
    public Sheet setCap(String id, String user, BigDecimal cap, LocalDate from) {
        return setDated(id, user, Sheet.CAP, money(cap), from, true);
    }

    /** Record the sheet's floor from a date, auditing the change and the figures it moves. */
    @Transactional
    public Sheet setFloor(String id, String user, BigDecimal floor, LocalDate from) {
        return setDated(id, user, Sheet.FLOOR, money(floor), from, true);
    }

    /** Record the sheet's terms, in days, from a date, auditing the change; claims keep their due-by. */
    @Transactional
    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
        return setDated(id, user, Sheet.TERMS, Integer.toString(terms), from, true);
    }

    /**
     * Record a grade's own terms, in days (null: the sheet's terms), from a date, auditing the change.
     * Claims keep their due-by.
     */
    @Transactional
    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
        return setDated(id, user, Sheet.gradeTermsKey(grade), terms == null ? null : terms.toString(), from, true);
    }

    /** Record the sheet's late percent from a date, auditing the change and the figures it moves. */
    @Transactional
    public Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
        return setDated(id, user, Sheet.LATE_PCT, money(latePct), from, true);
    }

    /**
     * Record a dated setting's value (null: none) from a date, the sheet's today when none is given,
     * replacing any value recorded from that date. The change is audited, with the from-date when one
     * was given, and so are the figures it moves when it can move any.
     */
    private Sheet setDated(String id, String user, String key, String value, LocalDate from, boolean movesFigures) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = movesFigures ? rollups.take(id) : null;
        sheet.record(key, from == null ? sheet.getToday() : from, value);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value="
                + (value == null ? "" : value) + (from == null ? "" : " from=" + from));
        if (movesFigures) {
            rollups.audit(id, user, before);
        }
        return saved;
    }

    /** A figure with two decimals as text; null stays null. */
    private static String money(BigDecimal value) {
        return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }

    /** Change the sheet's policy date (null: the sheet's today), auditing the change and the figures it moves. */
    @Transactional
    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
        Sheet sheet = lock(id);
        Rollups.Rollup before = rollups.take(id);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=policy-date value="
                + (saved.getPolicyDate() == null ? "" : saved.getPolicyDate().toString()));
        rollups.audit(id, user, before);
        return saved;
    }

    /** Change the sheet's period-numbering-from date (null: off), auditing the change. */
    @Transactional
    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
        Sheet sheet = lock(id);
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=period-numbering-from value="
                + (saved.getPeriodNumberingFrom() == null ? "" : saved.getPeriodNumberingFrom().toString()));
        return saved;
    }
}
package net.officefloor.hq.app.quickadd;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The quick-add bar: a DRAFT claim of an amount, dated the sheet's today with an empty note, for the
 * person of a name, who is first added with grade A when the name is not on the sheet. It is one
 * change: when the claim is refused the person added for it is not kept, and nothing is recorded.
 */
@Service
public class QuickAddService {

    /** The grade a person added by the quick-add bar is given. */
    static final String GRADE = "A";

    /** What a quick-add made: the claim, for its person, and whether that person was added for it. */
    public record Added(Person person, boolean personAdded, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        Person existing = people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name)).orElse(null);
        Person person = existing != null ? existing : personService.add(sheetId, user, name, GRADE);
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "", null);
        return new Added(person, existing == null, claim);
    }
}
package net.officefloor.hq.app.claim;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A line of a claim's status log: a status the claim moved to, by whom, on the sheet's today then,
 * and the claim's due as computed at that moment (null when n/a).
 */
@Entity
@Table(name = "claim_log")
public class ClaimLogLine {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private ClaimStatus status;

    @Column(name = "by_user", nullable = false)
    private String by;

    @Column(name = "on_date", nullable = false)
    private LocalDate on;

    @Column(name = "due", precision = 14, scale = 2)
    private BigDecimal due;

    protected ClaimLogLine() {
    }

    public ClaimLogLine(ClaimStatus status, String by, LocalDate on, BigDecimal due) {
        this.status = status;
        this.by = by;
        this.on = on;
        this.due = due;
    }

    public ClaimStatus getStatus() {
        return status;
    }

    public String getBy() {
        return by;
    }

    public LocalDate getOn() {
        return on;
    }

    public BigDecimal getDue() {
        return due;
    }
}
